public class LabelFormatterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            check("nulls are skipped", "a, b", LabelFormatter.joinNonNull(", ", "a", null, "b"));
            check("no parts at all", "", LabelFormatter.joinNonNull(", "));
            check("single part, no separator", "a", LabelFormatter.joinNonNull("-", "a"));
            check("all parts null", "", LabelFormatter.joinNonNull("|", null, null));
            check("separator only between", "x|y|z", LabelFormatter.joinNonNull("|", "x", "y", "z"));
            check("bullet list", "- one\n- two", LabelFormatter.bulletList("-", "one", "two"));
            check("empty bullet list", "", LabelFormatter.bulletList("-"));
            check("plural wording", "Ada: 3 values [1, 2, 3]", LabelFormatter.describe("Ada", 1, 2, 3));
            check("singular wording", "Bob: 1 value [5]", LabelFormatter.describe("Bob", 5));
            check("no values at all", "Cid: no values", LabelFormatter.describe("Cid"));
            check("an int array can be passed straight in", "Dee: 2 values [4, 9]",
                    LabelFormatter.describe("Dee", new int[] {4, 9}));
        } catch (Throwable t) {
            broke("LabelFormatter", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

