public class LabelFormatter {

    public static String joinNonNull(String separator, String... parts) {
        StringBuilder out = new StringBuilder();
        for (String part : parts) {
            if (part == null) {
                continue;
            }
            if (out.length() > 0) {
                out.append(separator);
            }
            out.append(part);
        }
        return out.toString();
    }

    public static String bulletList(String marker, String... items) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < items.length; i++) {
            if (i > 0) {
                out.append("\n");
            }
            out.append(marker).append(' ').append(items[i]);
        }
        return out.toString();
    }

    public static String describe(String label, int... values) {
        if (values.length == 0) {
            return label + ": no values";
        }
        String word = values.length == 1 ? "value" : "values";
        return label + ": " + values.length + " " + word + " " + java.util.Arrays.toString(values);
    }
}
